```json
{
  "clarified": "对豆包爱学进行全面竞品调研，覆盖产品定位、目标用户、产品形态、核心功能、商业模式及近半年动态更新等方面，结合公开资料与应用商店信息，最终形成对产品的完整认知报告。",
  "deliverable_type": "research",
  "iterative": true,
  "acceptance": [
    "报告覆盖产品定位与目标用户分析",
    "报告覆盖产品形态与核心功能梳理",
    "报告覆盖商业模式分析",
    "报告覆盖近半年的重要动态与更新",
    "各维度均有信息来源标注",
    "形成对豆包爱学产品的完整、连贯印象"
  ],
  "capabilities": [
    {
      "id": "plan_outline",
      "name": "规划大纲",
      "kind": "light",
      "desc": "根据调研目标生成报告大纲，规划章节结构、每章要点和各维度的调研方向，写入 blackboard 的 report_outline。不搜索、不产出文件，只做结构规划。",
      "agent": "",
      "outputs": [],
      "checks": [
        {
          "method": "llm_rubric",
          "desc": "大纲覆盖产品定位、目标用户、产品形态、核心功能、商业模式、近期动态等维度",
          "target": ""
        }
      ],
      "updates": ["report_outline"],
      "instances": [],
      "context_inputs": []
    },
    {
      "id": "search",
      "name": "搜索调研",
      "kind": "agent",
      "desc": "按大纲中规划的调研方向，针对该维度搜索豆包爱学相关信息。边搜边把原始结果追加写入文件，每条标注来源。不要求结构化、不要求整理——搜到一条写一条。",
      "agent": "researcher",
      "outputs": [
        {
          "path": "solution/search/{instance}.md",
          "desc": "该维度的原始搜索结果，每条标注来源",
          "role": "evidence",
          "materializable": true
        }
      ],
      "checks": [
        {
          "method": "file_exists",
          "desc": "搜索结果文件存在且有内容",
          "target": "solution/search/{instance}.md"
        },
        {
          "method": "llm_rubric",
          "desc": "搜索结果包含来源标注",
          "target": "solution/search/{instance}.md"
        }
      ],
      "updates": ["search_remaining"],
      "instances": [
        {
          "name": "product_positioning",
          "scope": "豆包爱学的产品定位、品牌背景、所属公司、目标用户群体、使用场景",
          "excludes": "具体功能介绍、商业模式、近期版本更新"
        },
        {
          "name": "product_features",
          "scope": "豆包爱学的产品形态（App/小程序/PC端）、核心功能模块、功能亮点、交互设计特点",
          "excludes": "产品定位与目标用户、商业模式、近期版本更新时间线"
        },
        {
          "name": "business_model",
          "scope": "豆包爱学的商业模式、收费策略、会员体系、变现路径、竞争策略",
          "excludes": "产品定位、具体功能介绍、近期版本更新时间线"
        },
        {
          "name": "recent_updates",
          "scope": "豆包爱学近半年的重要动态：版本更新、功能改版、重大上线、市场动作",
          "excludes": "产品定位、核心功能的基础介绍、商业模式"
        }
      ],
      "context_inputs": ["report_outline"]
    },
    {
      "id": "write_evidence",
      "name": "整理证据",
      "kind": "agent",
      "desc": "从对应的 search 文件读取原始搜索结果，整理成结构化证据文件。只整理不搜索——有明确输入和产出。按维度组织信息，去重合并，标注来源可信度。",
      "agent": "researcher",
      "outputs": [
        {
          "path": "solution/evidence/{instance}.md",
          "desc": "该维度的结构化证据整理",
          "role": "intermediate",
          "materializable": true
        }
      ],
      "checks": [
        {
          "method": "file_exists",
          "desc": "证据文件存在且有内容",
          "target": "solution/evidence/{instance}.md"
        },
        {
          "method": "llm_rubric",
          "desc": "证据内容结构化组织，有条理",
          "target": "solution/evidence/{instance}.md"
        }
      ],
      "updates": ["write_evidence_remaining", "evidence_index"],
      "instances": [
        {
          "name": "product_positioning",
          "scope": "整理产品定位与目标用户维度的证据",
          "excludes": "其他维度的内容"
        },
        {
          "name": "product_features",
          "scope": "整理产品形态与核心功能维度的证据",
          "excludes": "其他维度的内容"
        },
        {
          "name": "business_model",
          "scope": "整理商业模式维度的证据",
          "excludes": "其他维度的内容"
        },
        {
          "name": "recent_updates",
          "scope": "整理近期动态维度的证据",
          "excludes": "其他维度的内容"
        }
      ],
      "context_inputs": ["report_outline"]
    },
    {
      "id": "synthesize",
      "name": "综合撰写",
      "kind": "agent",
      "desc": "从所有维度 evidence 文件综合写成完整调研报告初稿。搜到的用真实来源，搜不到的用 LLM 知识标注为趋势推演。覆盖产品定位、目标用户、产品形态、核心功能、商业模式、近期动态等全部维度，形成连贯的产品认知。",
      "agent": "writer",
      "outputs": [
        {
          "path": "solution/report_draft.md",
          "desc": "完整调研报告初稿",
          "role": "deliverable",
          "materializable": true
        }
      ],
      "checks": [
        {
          "method": "llm_rubric",
          "desc": "报告覆盖全部调研维度（定位、用户、形态、功能、商业模式、动态）",
          "target": "solution/report_draft.md"
        },
        {
          "method": "llm_rubric",
          "desc": "报告形成对产品的完整、连贯印象",
          "target": "solution/report_draft.md"
        }
      ],
      "updates": [],
      "instances": [],
      "context_inputs": ["report_outline", "evidence_index"]
    },
    {
      "id": "polish_report",
      "name": "润色报告",
      "kind": "agent",
      "desc": "读报告初稿，做语言流畅度、逻辑连贯性、格式整洁度优化。确保各维度信息衔接自然，整体读起来像一个完整的产品认知。",
      "agent": "writer",
      "outputs": [
        {
          "path": "solution/report_final.md",
          "desc": "润色后的最终报告",
          "role": "deliverable",
          "materializable": true
        }
      ],
      "checks": [
        {
          "method": "llm_rubric",
          "desc": "报告语言流畅、逻辑连贯、格式整洁",
          "target": "solution/report_final.md"
        }
      ],
      "updates": [],
      "instances": [],
      "context_inputs": ["report_outline"]
    },
    {
      "id": "review_report",
      "name": "审校报告",
      "kind": "agent",
      "desc": "审校最终报告是否满足全部验收标准，逐项检查各维度覆盖度和认知深度。不通过则打回重修。",
      "agent": "reviewer",
      "outputs": [
        {
          "path": "solution/review_notes.md",
          "desc": "审校意见与通过/不通过结论",
          "role": "intermediate",
          "materializable": true
        }
      ],
      "checks": [
        {
          "method": "llm_rubric",
          "desc": "报告满足全部验收标准，各维度覆盖完整",
          "target": "solution/report_final.md"
        }
      ],
      "updates": [],
      "instances": [],
      "context_inputs": []
    }
  ],
  "guardrails": {
    "max_iterations": 20,
    "soft": [
      {
        "id": "search_depth",
        "desc": "如果某维度搜索结果明显不足（少于3条有效信息），应标记为知识缺口而非强行拼凑",
        "action": "stop_human"
      }
    ],
    "human_checkpoint_every": 0
  },
  "blackboard_schema": {
    "fields": [
      {
        "key": "report_outline",
        "desc": "报告大纲：章节结构+每章要点+各维度调研方向",
        "bounded": true
      },
      {
        "key": "search_remaining",
        "desc": "未完成的搜索实例列表",
        "bounded": true
      },
      {
        "key": "write_evidence_remaining",
        "desc": "未完成的证据整理实例列表",
        "bounded": true
      },
      {
        "key": "evidence_index",
        "desc": "已完成的 evidence 文件路径索引",
        "bounded": true
      }
    ]
  },
  "entry_node": "plan_outline",
  "completion_criteria": [
    "全部维度的 search 和 write_evidence 实例完成",
    "synthesize 生成的报告初稿覆盖全部维度",
    "polish 后的最终报告通过 review 审校",
    "报告达到竞品分析所需的认知深度"
  ],
  "hard_constraints": [
    "覆盖维度：产品定位、目标用户、产品形态、核心功能、商业模式、近半年动态",
    "时间范围：重点关注最近半年",
    "信息来源：公开资料加应用商店信息",
    "搜索结果必须标注来源"
  ],
  "soft_guidance": [
    "报告风格：简洁清晰，重点突出，不必过于正式",
    "信息取舍：优先关注差异化和创新点，而非罗列所有功能",
    "表达偏好：形成自己的判断和观点，而非纯信息堆砌"
  ],
  "deliverable_contract": {
    "required_sections": [],
    "forbidden_patterns": []
  },
  "agents": ["researcher", "writer", "reviewer"],
  "required_capabilities": ["web", "browser"],
  "selected_executor": "hermes",
  "skills": [],
  "scripts": [],
  "clarifications": []
}
```
